    {
      "name": "frontdesk.py",
      "title": "Module 4 \u00b7 Check-in / out",
      "purpose": "Check-in and check-out, executed as single atomic transactions.",
      "code": "\"\"\"\nfrontdesk.py\n============\nMODULE 4 - CHECK-IN AND CHECK-OUT MANAGEMENT\n\nCheck-in  : reservation Booked      -> CheckedIn   , room -> Occupied\nCheck-out : reservation CheckedIn   -> CheckedOut , room -> Available\n\nBoth operations change TWO tables, so they run inside a single\ntransaction (db.run_in_transaction).  If the second UPDATE failed for any\nreason, the first one would be undone as well - this is the classic\n\"either all or nothing\" property of a transaction.\n\"\"\"\n\nfrom datetime import date\n\nfrom db import DatabaseError\nfrom ui import (Cancel, ask_int, confirm, error, info, menu_choice, money,\n                pause, print_record, print_table, success, subtitle, title,\n                warn)\n\nimport payments\nimport reservations\n\n\ndef todays_arrivals(db):\n    subtitle(\"TODAY'S EXPECTED CHECK-INS\")\n    rows = db.query(\n        \"\"\"\n        SELECT r.reservation_id, c.customer_id, c.full_name, c.phone,\n               rm.room_number, rm.room_type, r.check_in_date, r.check_out_date,\n               r.num_guests, r.total_amount\n        FROM reservation r\n        INNER JOIN customer c ON c.customer_id = r.customer_id\n        INNER JOIN room rm    ON rm.room_id    = r.room_id\n        WHERE r.status = 'Booked'\n          AND r.check_in_date = CURRENT_DATE\n        ORDER BY r.reservation_id\n        \"\"\")\n    print_table(rows, [\n        (\"reservation_id\", \"Resv\", 5, \"r\"),\n        (\"customer_id\", \"Cust\", 5, \"r\"),\n        (\"full_name\", \"Guest\", 20, \"l\"),\n        (\"phone\", \"Phone\", 11, \"l\"),\n        (\"room_number\", \"Room\", 6, \"l\"),\n        (\"room_type\", \"Type\", 8, \"l\"),\n        (\"num_guests\", \"Guests\", 7, \"r\"),\n        (\"total_amount\", \"Amount\", 11, \"r\"),\n    ], empty_message=\"No reservation starts today.\")\n\n\ndef todays_departures(db):\n    subtitle(\"TODAY'S EXPECTED CHECK-OUTS\")\n    rows = db.query(\n        \"\"\"\n        SELECT r.reservation_id, c.full_name, rm.room_number, rm.room_type,\n               r.check_in_date, r.check_out_date, r.total_amount,\n               COALESCE(p.payment_status, 'Not Paid') AS payment_status\n        FROM reservation r\n        INNER JOIN customer c ON c.customer_id = r.customer_id\n        INNER JOIN room rm    ON rm.room_id    = r.room_id\n        LEFT JOIN payment p   ON p.reservation_id = r.reservation_id\n        WHERE r.status = 'CheckedIn'\n          AND r.check_out_date <= CURRENT_DATE\n        ORDER BY r.reservation_id\n        \"\"\")\n    print_table(rows, [\n        (\"reservation_id\", \"Resv\", 5, \"r\"),\n        (\"full_name\", \"Guest\", 20, \"l\"),\n        (\"room_number\", \"Room\", 6, \"l\"),\n        (\"room_type\", \"Type\", 8, \"l\"),\n        (\"check_out_date\", \"Due\", 11, \"l\"),\n        (\"total_amount\", \"Amount\", 11, \"r\"),\n        (\"payment_status\", \"Payment\", 11, \"l\"),\n    ], empty_message=\"No guest is due to leave today.\")\n\n\n# ----------------------------------------------------------------------\n# Check-in\n# ----------------------------------------------------------------------\ndef check_in(db):\n    subtitle(\"RECORD CUSTOMER CHECK-IN\")\n    try:\n        reservation_id = ask_int(\"Reservation ID\", minimum=1)\n    except Cancel:\n        return\n\n    row = reservations.get_reservation(db, reservation_id)\n    if not row:\n        error(f\"No reservation with ID {reservation_id}.\")\n        return\n\n    print()\n    reservations.print_reservation(row)\n\n    if row[\"status\"] == \"CheckedIn\":\n        warn(\"This guest has already been checked in.\")\n        return\n    if row[\"status\"] != \"Booked\":\n        error(f\"A reservation with status '{row['status']}' cannot be checked in.\")\n        return\n    if row[\"check_in_date\"] > date.today():\n        warn(f\"Check-in date is {row['check_in_date']}, \"\n             \"which is in the future. Check-in is not allowed yet.\")\n        return\n\n    room = db.query_one(\n        \"SELECT room_id, room_number, status FROM room WHERE room_number = %s\",\n        (row[\"room_number\"],))\n    if room[\"status\"] == \"Maintenance\":\n        error(\"This room is under maintenance and cannot be occupied.\")\n        return\n    if room[\"status\"] == \"Occupied\":\n        error(\"The room is already marked Occupied. Please verify with the \"\n              \"front desk before checking in.\")\n        return\n\n    if not confirm(f\"Check in {row['customer_name']} to room \"\n                   f\"{row['room_number']}?\"):\n        info(\"Check-in cancelled.\")\n        return\n\n    # Two statements, one transaction.\n    try:\n        db.run_in_transaction([\n            (\"\"\"\n             UPDATE reservation\n                SET status = 'CheckedIn',\n                    actual_check_in = CURRENT_TIMESTAMP\n              WHERE reservation_id = %s AND status = 'Booked'\n             \"\"\", (reservation_id,)),\n            (\"\"\"\n             UPDATE room\n                SET status = 'Occupied'\n              WHERE room_id = %s AND status = 'Available'\n             \"\"\", (room[\"room_id\"],)),\n        ])\n    except DatabaseError as exc:\n        error(f\"Check-in failed and was rolled back.\\n  {exc}\")\n        return\n\n    success(f\"Check-in recorded for reservation {reservation_id}.\")\n    print_record({\n        \"Guest\": row[\"customer_name\"],\n        \"Room\": f\"{row['room_number']} ({row['room_type']})\",\n        \"Check-in\": row[\"check_in_date\"],\n        \"Planned check-out\": row[\"check_out_date\"],\n        \"Room status\": \"Occupied\",\n        \"Reservation status\": \"CheckedIn\",\n    })\n\n    if row[\"payment_status\"] != \"Paid\":\n        warn(f\"Payment for this reservation is '{row['payment_status']}'.\")\n        if confirm(\"Record the payment now?\"):\n            payments.record_payment_for(db, reservation_id)\n\n\n# ----------------------------------------------------------------------\n# Check-out\n# ----------------------------------------------------------------------\ndef check_out(db):\n    subtitle(\"RECORD CUSTOMER CHECK-OUT\")\n    try:\n        reservation_id = ask_int(\"Reservation ID\", minimum=1)\n    except Cancel:\n        return\n\n    row = reservations.get_reservation(db, reservation_id)\n    if not row:\n        error(f\"No reservation with ID {reservation_id}.\")\n        return\n\n    print()\n    reservations.print_reservation(row)\n\n    if row[\"status\"] == \"CheckedOut\":\n        warn(\"This guest has already been checked out.\")\n        return\n    if row[\"status\"] != \"CheckedIn\":\n        error(f\"A reservation with status '{row['status']}' cannot be checked out.\")\n        return\n\n    room = db.query_one(\"SELECT room_id FROM room WHERE room_number = %s\",\n                        (row[\"room_number\"],))\n\n    print(\"\\nFinal bill\")\n    print(\"  \" + \"-\" * 46)\n    print(f\"  Room charge        : Rs. {money(row['total_amount'])}\")\n    print(f\"  Payment status     : {row['payment_status']}\")\n    print(\"  \" + \"-\" * 46)\n\n    if row[\"payment_status\"] != \"Paid\":\n        warn(\"The bill has not been paid yet.\")\n        if not confirm(\"Record the payment before check-out?\"):\n            if not confirm(\"Continue check-out with payment still pending?\"):\n                info(\"Check-out cancelled.\")\n                return\n        else:\n            payments.record_payment_for(db, reservation_id)\n\n    if not confirm(f\"Check out {row['customer_name']} from room \"\n                   f\"{row['room_number']}?\"):\n        info(\"Check-out cancelled.\")\n        return\n\n    try:\n        db.run_in_transaction([\n            (\"\"\"\n             UPDATE reservation\n                SET status = 'CheckedOut',\n                    actual_check_out = CURRENT_TIMESTAMP\n              WHERE reservation_id = %s AND status = 'CheckedIn'\n             \"\"\", (reservation_id,)),\n            (\"\"\"\n             UPDATE room\n                SET status = 'Available'\n              WHERE room_id = %s\n             \"\"\", (room[\"room_id\"],)),\n        ])\n    except DatabaseError as exc:\n        error(f\"Check-out failed and was rolled back.\\n  {exc}\")\n        return\n\n    success(f\"Check-out recorded for reservation {reservation_id}.\")\n    print_record({\n        \"Guest\": row[\"customer_name\"],\n        \"Room\": f\"{row['room_number']} ({row['room_type']})\",\n        \"Amount billed\": money(row[\"total_amount\"]),\n        \"Payment status\": row[\"payment_status\"],\n        \"Room status\": \"Available (free for the next guest)\",\n        \"Reservation status\": \"CheckedOut\",\n    })\n\n\n# ----------------------------------------------------------------------\n# Menu\n# ----------------------------------------------------------------------\ndef menu(db):\n    while True:\n        title(\"CHECK-IN / CHECK-OUT MANAGEMENT\")\n        print(\"  1. Record check-in\")\n        print(\"  2. Record check-out\")\n        print(\"  3. Show today's expected check-ins\")\n        print(\"  4. Show today's expected check-outs\")\n        print(\"  0. Back to main menu\")\n        try:\n            choice = menu_choice()\n        except Cancel:\n            return\n        try:\n            if choice == \"1\":\n                check_in(db)\n            elif choice == \"2\":\n                check_out(db)\n            elif choice == \"3\":\n                todays_arrivals(db)\n            elif choice == \"4\":\n                todays_departures(db)\n            elif choice == \"0\":\n                return\n            else:\n                error(\"Invalid option. Please choose a number from the menu.\")\n                continue\n        except DatabaseError as exc:\n            error(str(exc))\n        pause()\n",
      "lines": 266
    },
    {
      "name": "payments.py",
      "title": "Module 5 \u00b7 Payments",
      "purpose": "Record payments (Cash / Card / UPI), pending list and refunds.",
      "code": "\"\"\"\npayments.py\n===========\nMODULE 5 - PAYMENT MANAGEMENT\n\nA payment row is created together with every reservation with status\n'Pending'.  This module records the money actually received and changes\nthe status to 'Paid', or marks a paid amount as 'Refunded' when a\nreservation is cancelled.\n\nPayment methods allowed by the CHECK constraint: Cash, Card, UPI.\nPayment statuses: Pending, Paid, Refunded.\n\"\"\"\n\nfrom db import DatabaseError\nfrom ui import (Cancel, ask, ask_choice, ask_int, confirm, error, info,\n                menu_choice, money, pause, print_record, print_table,\n                success, subtitle, title, warn)\n\nPAYMENT_METHODS = [\"Cash\", \"Card\", \"UPI\"]\nPAYMENT_STATUSES = [\"Pending\", \"Paid\", \"Refunded\"]\n\nPAYMENT_COLUMNS = [\n    (\"payment_id\", \"Pay ID\", 6, \"r\"),\n    (\"reservation_id\", \"Resv\", 5, \"r\"),\n    (\"customer_name\", \"Customer\", 18, \"l\"),\n    (\"room_number\", \"Room\", 6, \"l\"),\n    (\"amount\", \"Amount\", 11, \"r\"),\n    (\"payment_method\", \"Method\", 8, \"l\"),\n    (\"payment_status\", \"Status\", 10, \"l\"),\n    (\"payment_date\", \"Paid on\", 16, \"l\"),\n    (\"transaction_ref\", \"Reference\", 13, \"l\"),\n]\n\n\ndef show_payments(rows, empty_message=\"No payments found.\"):\n    print_table(rows, PAYMENT_COLUMNS, empty_message=empty_message)\n\n\ndef payment_for(db, reservation_id: int):\n    return db.query_one(\n        \"SELECT * FROM vw_payment_details WHERE reservation_id = %s\",\n        (reservation_id,))\n\n\n# ----------------------------------------------------------------------\n# 1. Record payment for an existing reservation (used by the menu and\n#    also automatically from check-in / check-out)\n# ----------------------------------------------------------------------\ndef record_payment_for(db, reservation_id: int):\n    \"\"\"Ask for the method and mark the reservation's payment as Paid.\"\"\"\n    reservation = db.query_one(\n        \"SELECT * FROM vw_reservation_details WHERE reservation_id = %s\",\n        (reservation_id,))\n    if not reservation:\n        error(f\"No reservation with ID {reservation_id}.\")\n        return\n\n    print(\"\\nReservation to be paid:\")\n    print_record(reservation, labels={\n        \"reservation_id\": \"Reservation ID\",\n        \"customer_id\": \"Customer ID\",\n        \"customer_name\": \"Customer\",\n        \"customer_phone\": \"Phone\",\n        \"room_number\": \"Room\",\n        \"room_type\": \"Room type\",\n        \"price_per_night\": \"Price per night\",\n        \"check_in_date\": \"Check-in\",\n        \"check_out_date\": \"Check-out\",\n        \"nights\": \"Nights\",\n        \"num_guests\": \"Guests\",\n        \"total_amount\": \"Bill amount\",\n        \"status\": \"Status\",\n        \"payment_status\": \"Payment status\",\n    })\n\n    if reservation[\"status\"] == \"Cancelled\":\n        error(\"This reservation is cancelled; there is nothing to collect.\")\n        return\n\n    existing = db.query_one(\n        \"SELECT * FROM payment WHERE reservation_id = %s\", (reservation_id,))\n    if existing and existing[\"payment_status\"] == \"Paid\":\n        info(f\"Payment for reservation {reservation_id} is already recorded \"\n             f\"(Rs. {money(existing['amount'])} on {existing['payment_date']}).\")\n        return\n\n    amount = reservation[\"total_amount\"]\n    try:\n        method = ask_choice(\"Payment method\", PAYMENT_METHODS)\n        reference = \"\"\n        if method in (\"Card\", \"UPI\"):\n            reference = ask(\"Transaction reference (press ENTER to skip)\",\n                            required=False)\n        if not confirm(f\"Collect Rs. {money(amount)} by {method}?\"):\n            info(\"Payment cancelled.\")\n            return\n    except Cancel:\n        info(\"Payment cancelled.\")\n        return\n\n    try:\n        if existing:\n            db.execute(\n                \"\"\"\n                UPDATE payment\n                   SET payment_status = 'Paid',\n                       payment_method = %s,\n                       amount = %s,\n                       payment_date = CURRENT_TIMESTAMP,\n                       transaction_ref = %s\n                 WHERE payment_id = %s\n                \"\"\",\n                (method, amount, reference or None, existing[\"payment_id\"]))\n        else:\n            db.execute(\n                \"\"\"\n                INSERT INTO payment\n                    (reservation_id, amount, payment_method, payment_status,\n                     transaction_ref)\n                VALUES (%s, %s, %s, 'Paid', %s)\n                \"\"\",\n                (reservation_id, amount, method, reference or None))\n    except DatabaseError as exc:\n        error(f\"Could not record the payment.\\n  {exc}\")\n        return\n\n    success(f\"Payment of Rs. {money(amount)} recorded as Paid ({method}).\")\n    row = payment_for(db, reservation_id)\n    if row:\n        print_record(row, labels={\n            \"payment_id\": \"Payment ID\",\n            \"reservation_id\": \"Reservation\",\n            \"customer_name\": \"Customer\",\n            \"room_number\": \"Room\",\n            \"amount\": \"Amount\",\n            \"payment_method\": \"Method\",\n            \"payment_status\": \"Status\",\n            \"payment_date\": \"Date\",\n            \"transaction_ref\": \"Reference\",\n        })\n\n\n# ----------------------------------------------------------------------\n# 2. Record a payment by reservation id (menu entry)\n# ----------------------------------------------------------------------\ndef record_payment(db):\n    subtitle(\"RECORD A PAYMENT\")\n    try:\n        reservation_id = ask_int(\"Reservation ID\", minimum=1)\n    except Cancel:\n        return\n    record_payment_for(db, reservation_id)\n\n\n# ----------------------------------------------------------------------\n# 3. View payments\n# ----------------------------------------------------------------------\ndef view_payments(db):\n    subtitle(\"PAYMENT DETAILS\")\n    print(\"  1. All payments\")\n    print(\"  2. Only Pending\")\n    print(\"  3. Only Paid\")\n    print(\"  4. Only Refunded\")\n    try:\n        choice = menu_choice(\"Choose a filter\")\n    except Cancel:\n        return\n\n    mapping = {\"2\": \"Pending\", \"3\": \"Paid\", \"4\": \"Refunded\"}\n    if choice in mapping:\n        rows = db.query(\n            \"SELECT * FROM vw_payment_details WHERE payment_status = %s \"\n            \"ORDER BY payment_id\", (mapping[choice],))\n    elif choice == \"1\":\n        rows = db.query(\"SELECT * FROM vw_payment_details ORDER BY payment_id\")\n    else:\n        error(\"Invalid filter option.\")\n        return\n\n    show_payments(rows)\n    if rows:\n        total = sum(r[\"amount\"] for r in rows)\n        print(f\"\\nTotal of the rows shown: Rs. {money(total)}\")\n\n\n# ----------------------------------------------------------------------\n# 4. Refund a payment\n# ----------------------------------------------------------------------\ndef refund_payment(db):\n    subtitle(\"MARK A PAYMENT AS REFUNDED\")\n    try:\n        payment_id = ask_int(\"Payment ID\", minimum=1)\n    except Cancel:\n        return\n\n    row = db.query_one(\"SELECT * FROM vw_payment_details WHERE payment_id = %s\",\n                       (payment_id,))\n    if not row:\n        error(f\"No payment with ID {payment_id}.\")\n        return\n    print()\n    print_record(row, labels={\n        \"payment_id\": \"Payment ID\",\n        \"reservation_id\": \"Reservation\",\n        \"customer_name\": \"Customer\",\n        \"room_number\": \"Room\",\n        \"amount\": \"Amount\",\n        \"payment_method\": \"Method\",\n        \"payment_status\": \"Status\",\n        \"payment_date\": \"Date\",\n        \"transaction_ref\": \"Reference\",\n    })\n\n    if row[\"payment_status\"] == \"Refunded\":\n        warn(\"This payment is already refunded.\")\n        return\n    if row[\"payment_status\"] != \"Paid\":\n        error(\"Only a Paid payment can be refunded.\")\n        return\n\n    if not confirm(f\"Refund Rs. {money(row['amount'])} to \"\n                   f\"{row['customer_name']}?\"):\n        info(\"Refund cancelled.\")\n        return\n\n    try:\n        db.execute(\n            \"UPDATE payment SET payment_status = 'Refunded' WHERE payment_id = %s\",\n            (payment_id,))\n    except DatabaseError as exc:\n        error(f\"Could not update the payment.\\n  {exc}\")\n        return\n    success(f\"Payment {payment_id} marked as Refunded.\")\n\n\n# ----------------------------------------------------------------------\n# 5. Pending payments list (front-desk follow-up)\n# ----------------------------------------------------------------------\ndef pending_payments(db):\n    subtitle(\"PAYMENTS STILL PENDING\")\n    rows = db.query(\n        \"\"\"\n        SELECT * FROM vw_payment_details\n        WHERE payment_status = 'Pending'\n        ORDER BY payment_id\n        \"\"\")\n    show_payments(rows, empty_message=\"Every reservation has been paid.\")\n    if rows:\n        total = sum(r[\"amount\"] for r in rows)\n        print(f\"\\nOutstanding amount: Rs. {money(total)}\")\n\n\n# ----------------------------------------------------------------------\n# Menu\n# ----------------------------------------------------------------------\ndef menu(db):\n    while True:\n        title(\"PAYMENT MANAGEMENT\")\n        print(\"  1. Record a payment for a reservation\")\n        print(\"  2. View payment details\")\n        print(\"  3. Show pending payments\")\n        print(\"  4. Mark a payment as refunded\")\n        print(\"  0. Back to main menu\")\n        try:\n            choice = menu_choice()\n        except Cancel:\n            return\n        try:\n            if choice == \"1\":\n                record_payment(db)\n            elif choice == \"2\":\n                view_payments(db)\n            elif choice == \"3\":\n                pending_payments(db)\n            elif choice == \"4\":\n                refund_payment(db)\n            elif choice == \"0\":\n                return\n            else:\n                error(\"Invalid option. Please choose a number from the menu.\")\n                continue\n        except DatabaseError as exc:\n            error(str(exc))\n        pause()\n",
      "lines": 285
    },
    {
      "name": "reports.py",
      "title": "Module 6 \u00b7 Reports",
      "purpose": "Eight reports built with joins, GROUP BY, HAVING, subqueries and views.",
      "code": "\"\"\"\nreports.py\n==========\nMODULE 6 - REPORTS AND SEARCH\n\nEach function below is one report of the project.  The SQL used is also\nuseful for the viva: joins, LEFT JOIN, GROUP BY, HAVING, aggregate\nfunctions, subqueries, ORDER BY and views all appear here.\n\"\"\"\n\nfrom datetime import date\n\nfrom db import DatabaseError\nfrom ui import (Cancel, ask, ask_date, error, menu_choice, money,\n                pause, print_table, subtitle, title, warn)\n\nimport reservations\n\n\n# ----------------------------------------------------------------------\n# 1. All reservations\n# ----------------------------------------------------------------------\ndef all_reservations(db):\n    subtitle(\"REPORT 1: ALL RESERVATIONS\")\n    rows = db.query(\n        \"SELECT * FROM vw_reservation_details ORDER BY reservation_id\")\n    reservations.show_reservations(rows)\n    if rows:\n        booked = sum(float(r[\"total_amount\"]) for r in rows\n                     if r[\"status\"] != \"Cancelled\")\n        print(f\"\\nBooking value (excluding cancelled): Rs. {money(booked)}\")\n\n\n# ----------------------------------------------------------------------\n# 2. Currently occupied rooms\n# ----------------------------------------------------------------------\ndef occupied_rooms(db):\n    subtitle(\"REPORT 2: CURRENTLY OCCUPIED ROOMS\")\n    rows = db.query(\n        \"\"\"\n        SELECT rm.room_number, rm.room_type, rm.price_per_night,\n               c.full_name AS guest_name, c.phone,\n               r.check_in_date, r.check_out_date,\n               (r.check_out_date - CURRENT_DATE) AS days_left\n        FROM room rm\n        INNER JOIN reservation r\n                ON r.room_id = rm.room_id AND r.status = 'CheckedIn'\n        INNER JOIN customer c ON c.customer_id = r.customer_id\n        ORDER BY rm.room_number\n        \"\"\")\n    print_table(rows, [\n        (\"room_number\", \"Room\", 6, \"l\"),\n        (\"room_type\", \"Type\", 9, \"l\"),\n        (\"guest_name\", \"Guest\", 18, \"l\"),\n        (\"phone\", \"Phone\", 11, \"l\"),\n        (\"check_in_date\", \"Check-in\", 11, \"l\"),\n        (\"check_out_date\", \"Check-out\", 11, \"l\"),\n        (\"days_left\", \"Days left\", 9, \"r\"),\n        (\"price_per_night\", \"Tariff\", 10, \"r\"),\n    ], empty_message=\"No guest is currently checked in.\")\n    total_rooms = db.scalar(\"SELECT COUNT(*) FROM room\", default=0)\n    if total_rooms:\n        print(f\"\\nOccupancy: {len(rows)} of {total_rooms} rooms \"\n              f\"({len(rows) * 100 / total_rooms:.1f}%)\")\n\n\n# ----------------------------------------------------------------------\n# 3. Available rooms\n# ----------------------------------------------------------------------\ndef available_rooms(db):\n    subtitle(\"REPORT 3: ROOMS AVAILABLE RIGHT NOW\")\n    rows = db.query(\n        \"\"\"\n        SELECT room_number, room_type, floor_no, price_per_night,\n               max_occupancy\n        FROM room\n        WHERE status = 'Available'\n        ORDER BY price_per_night\n        \"\"\")\n    print_table(rows, [\n        (\"room_number\", \"Room\", 6, \"l\"),\n        (\"room_type\", \"Type\", 9, \"l\"),\n        (\"floor_no\", \"Floor\", 6, \"r\"),\n        (\"max_occupancy\", \"Max guests\", 11, \"r\"),\n        (\"price_per_night\", \"Price/night\", 12, \"r\"),\n    ], empty_message=\"No room is available right now.\")\n\n    maintenance = db.scalar(\n        \"SELECT COUNT(*) FROM room WHERE status = 'Maintenance'\", default=0)\n    print(f\"\\nAvailable: {len(rows)} room(s). \"\n          f\"Under maintenance: {maintenance}.\")\n\n\n# ----------------------------------------------------------------------\n# 4. Customer booking history\n# ----------------------------------------------------------------------\ndef customer_history(db):\n    subtitle(\"REPORT 4: CUSTOMER BOOKING HISTORY\")\n    rows = db.query(\n        \"\"\"\n        SELECT customer_id, full_name, phone, total_bookings,\n               completed_stays, cancelled_bookings, total_spent\n        FROM vw_customer_booking_history\n        ORDER BY total_spent DESC, full_name\n        \"\"\")\n    print_table(rows, [\n        (\"customer_id\", \"ID\", 4, \"r\"),\n        (\"full_name\", \"Customer\", 20, \"l\"),\n        (\"phone\", \"Phone\", 11, \"l\"),\n        (\"total_bookings\", \"Bookings\", 9, \"r\"),\n        (\"completed_stays\", \"Completed\", 10, \"r\"),\n        (\"cancelled_bookings\", \"Cancelled\", 10, \"r\"),\n        (\"total_spent\", \"Total spent\", 13, \"r\"),\n    ])\n\n\ndef one_customer_history(db):\n    subtitle(\"REPORT 4b: BOOKING HISTORY OF ONE CUSTOMER\")\n    import customers\n    customer_id = customers.choose_customer(db)\n    if customer_id is None:\n        return\n\n    rows = db.query(\n        \"\"\"\n        SELECT * FROM vw_reservation_details\n        WHERE customer_id = %s\n        ORDER BY check_in_date\n        \"\"\", (customer_id,))\n    reservations.show_reservations(\n        rows, empty_message=\"This customer has no bookings.\")\n\n    summary = db.query_one(\n        \"SELECT * FROM vw_customer_booking_history WHERE customer_id = %s\",\n        (customer_id,))\n    if summary:\n        print(\"\\nSummary\")\n        print(\"  \" + \"-\" * 46)\n        print(f\"  Total bookings      : {summary['total_bookings']}\")\n        print(f\"  Completed stays     : {summary['completed_stays']}\")\n        print(f\"  Cancelled bookings  : {summary['cancelled_bookings']}\")\n        print(f\"  Total amount spent  : Rs. {money(summary['total_spent'])}\")\n\n\n# ----------------------------------------------------------------------\n# 5. Total revenue\n# ----------------------------------------------------------------------\ndef revenue_report(db):\n    subtitle(\"REPORT 5: TOTAL HOTEL REVENUE\")\n    summary = db.query_one(\n        \"\"\"\n        SELECT COUNT(*)               AS paid_transactions,\n               COALESCE(SUM(amount), 0)   AS total_revenue,\n               COALESCE(AVG(amount), 0)   AS average_payment,\n               COALESCE(MIN(amount), 0)   AS smallest_payment,\n               COALESCE(MAX(amount), 0)   AS largest_payment\n        FROM payment\n        WHERE payment_status = 'Paid'\n        \"\"\")\n    print(\"Revenue collected (payments with status = Paid)\\n\")\n    print(\"  \" + \"-\" * 52)\n    print(f\"  Number of paid transactions : {summary['paid_transactions']}\")\n    print(f\"  Total revenue               : Rs. {money(summary['total_revenue'])}\")\n    print(f\"  Average payment             : Rs. {money(summary['average_payment'])}\")\n    print(f\"  Smallest payment            : Rs. {money(summary['smallest_payment'])}\")\n    print(f\"  Largest payment             : Rs. {money(summary['largest_payment'])}\")\n    print(\"  \" + \"-\" * 52)\n\n    print(\"\\nRevenue by payment method (GROUP BY)\")\n    rows = db.query(\n        \"\"\"\n        SELECT payment_method, COUNT(*) AS transactions, SUM(amount) AS revenue\n        FROM payment\n        WHERE payment_status = 'Paid'\n        GROUP BY payment_method\n        ORDER BY revenue DESC\n        \"\"\")\n    print_table(rows, [\n        (\"payment_method\", \"Method\", 8, \"l\"),\n        (\"transactions\", \"Transactions\", 13, \"r\"),\n        (\"revenue\", \"Revenue\", 13, \"r\"),\n    ])\n\n    print(\"\\nRevenue by month (GROUP BY on payment_date)\")\n    rows = db.query(\n        \"\"\"\n        SELECT TO_CHAR(payment_date, 'Mon YYYY') AS month,\n               COUNT(*)                          AS transactions,\n               SUM(amount)                       AS revenue\n        FROM payment\n        WHERE payment_status = 'Paid'\n        GROUP BY TO_CHAR(payment_date, 'Mon YYYY'),\n                 DATE_TRUNC('month', payment_date)\n        ORDER BY DATE_TRUNC('month', payment_date)\n        \"\"\")\n    print_table(rows, [\n        (\"month\", \"Month\", 12, \"l\"),\n        (\"transactions\", \"Transactions\", 13, \"r\"),\n        (\"revenue\", \"Revenue\", 13, \"r\"),\n    ])\n\n    other = db.query_one(\n        \"\"\"\n        SELECT COALESCE(SUM(amount) FILTER (WHERE payment_status = 'Pending'), 0)\n                    AS pending,\n               COALESCE(SUM(amount) FILTER (WHERE payment_status = 'Refunded'), 0)\n                    AS refunded\n        FROM payment\n        \"\"\")\n    print(f\"\\nPending amount : Rs. {money(other['pending'])}\")\n    print(f\"Refunded amount: Rs. {money(other['refunded'])}\")\n\n\n# ----------------------------------------------------------------------\n# 6. Most frequently booked room type\n# ----------------------------------------------------------------------\ndef popular_room_type(db):\n    subtitle(\"REPORT 6: MOST FREQUENTLY BOOKED ROOM TYPE\")\n    rows = db.query(\n        \"\"\"\n        SELECT rm.room_type,\n               COUNT(*) AS times_booked,\n               SUM(r.total_amount) AS booking_value\n        FROM reservation r\n        INNER JOIN room rm ON rm.room_id = r.room_id\n        WHERE r.status <> 'Cancelled'\n        GROUP BY rm.room_type\n        ORDER BY times_booked DESC, rm.room_type\n        \"\"\")\n    if not rows:\n        warn(\"No confirmed reservations yet.\")\n        return\n\n    print_table(rows, [\n        (\"room_type\", \"Room type\", 10, \"l\"),\n        (\"times_booked\", \"Times booked\", 13, \"r\"),\n        (\"booking_value\", \"Booking value\", 15, \"r\"),\n    ])\n    best = rows[0]\n    print(f\"\\nMost frequently booked room type: {best['room_type']} \"\n          f\"({best['times_booked']} confirmed bookings)\")\n\n\n# ----------------------------------------------------------------------\n# 7. Occupancy summary\n# ----------------------------------------------------------------------\ndef occupancy_summary(db):\n    subtitle(\"REPORT 7: ROOM STATUS SUMMARY\")\n    rows = db.query(\n        \"\"\"\n        SELECT status,\n               COUNT(*) AS rooms,\n               ROUND(COUNT(*) * 100.0 / SUM(COUNT(*)) OVER (), 1) AS percentage\n        FROM room\n        GROUP BY status\n        ORDER BY rooms DESC\n        \"\"\")\n    print_table(rows, [\n        (\"status\", \"Room status\", 12, \"l\"),\n        (\"rooms\", \"Rooms\", 6, \"r\"),\n        (\"percentage\", \"Percentage\", 11, \"r\"),\n    ])\n\n    print(\"\\nRoom type performance (reservations + revenue)\")\n    rows = db.query(\n        \"\"\"\n        SELECT rm.room_type,\n               COUNT(rm.room_id)                                        AS total_rooms,\n               COUNT(r.reservation_id)                                  AS bookings,\n               COUNT(r.reservation_id) FILTER (WHERE r.status = 'CheckedIn')\n                                                                        AS in_house,\n               COALESCE(SUM(r.total_amount) FILTER (WHERE r.status <> 'Cancelled'), 0)\n                                                                        AS booking_value\n        FROM room rm\n        LEFT JOIN reservation r ON r.room_id = rm.room_id\n        GROUP BY rm.room_type\n        ORDER BY booking_value DESC\n        \"\"\")\n    print_table(rows, [\n        (\"room_type\", \"Room type\", 10, \"l\"),\n        (\"total_rooms\", \"Rooms\", 6, \"r\"),\n        (\"bookings\", \"Bookings\", 9, \"r\"),\n        (\"in_house\", \"In house\", 9, \"r\"),\n        (\"booking_value\", \"Booking value\", 15, \"r\"),\n    ])\n\n    arrivals = db.scalar(\n        \"SELECT COUNT(*) FROM reservation WHERE check_in_date = CURRENT_DATE\",\n        default=0)\n    departures = db.scalar(\n        \"SELECT COUNT(*) FROM reservation WHERE check_out_date = CURRENT_DATE\",\n        default=0)\n    in_house = db.scalar(\n        \"SELECT COUNT(*) FROM reservation WHERE status = 'CheckedIn'\",\n        default=0)\n\n    print(\"\\nDays business summary\")\n    print(\"  \" + \"-\" * 52)\n    print(f\"  Arrivals today   : {arrivals}\")\n    print(f\"  Departures today : {departures}\")\n    print(f\"  Guests in house  : {in_house}\")\n\n\n# ----------------------------------------------------------------------\n# 8. Search reservations\n# ----------------------------------------------------------------------\ndef search_reservations(db):\n    subtitle(\"SEARCH RESERVATIONS\")\n    print(\"  1. By customer name / phone / customer ID\")\n    print(\"  2. By date (reservations active on that date)\")\n    print(\"  3. By status\")\n    try:\n        choice = menu_choice(\"Choose a search option\")\n        if choice == \"1\":\n            keyword = ask(\"Customer name, phone or customer ID\")\n            rows = db.query(\n                \"\"\"\n                SELECT * FROM vw_reservation_details\n                WHERE LOWER(customer_name) LIKE LOWER(%s)\n                   OR customer_phone = %s\n                   OR CAST(customer_id AS TEXT) = %s\n                ORDER BY reservation_id\n                \"\"\", (f\"%{keyword}%\", keyword, keyword))\n        elif choice == \"2\":\n            day = ask_date(\"Date (YYYY-MM-DD)\", default=str(date.today()))\n            rows = db.query(\n                \"\"\"\n                SELECT * FROM vw_reservation_details\n                WHERE %s BETWEEN check_in_date AND check_out_date - 1\n                  AND status <> 'Cancelled'\n                ORDER BY room_number\n                \"\"\", (day,))\n            print(f\"\\nReservations staying on {day}:\")\n        elif choice == \"3\":\n            status = ask(\"Status (Booked / CheckedIn / CheckedOut / Cancelled)\")\n            rows = db.query(\n                \"SELECT * FROM vw_reservation_details WHERE status = %s \"\n                \"ORDER BY reservation_id\", (status,))\n        else:\n            error(\"Invalid search option.\")\n            return\n    except Cancel:\n        return\n\n    reservations.show_reservations(\n        rows, empty_message=\"No reservation matched your search.\")\n\n\n# ----------------------------------------------------------------------\n# Menu\n# ----------------------------------------------------------------------\ndef menu(db):\n    while True:\n        title(\"REPORTS AND SEARCH\")\n        print(\"  1. All reservations\")\n        print(\"  2. Currently occupied rooms\")\n        print(\"  3. Available rooms\")\n        print(\"  4. Customer booking history (all customers)\")\n        print(\"  5. Booking history of one customer\")\n        print(\"  6. Total hotel revenue\")\n        print(\"  7. Most frequently booked room type\")\n        print(\"  8. Room status / occupancy summary\")\n        print(\"  9. Search reservations\")\n        print(\"  0. Back to main menu\")\n        try:\n            choice = menu_choice()\n        except Cancel:\n            return\n        try:\n            if choice == \"1\":\n                all_reservations(db)\n            elif choice == \"2\":\n                occupied_rooms(db)\n            elif choice == \"3\":\n                available_rooms(db)\n            elif choice == \"4\":\n                customer_history(db)\n            elif choice == \"5\":\n                one_customer_history(db)\n            elif choice == \"6\":\n                revenue_report(db)\n            elif choice == \"7\":\n                popular_room_type(db)\n            elif choice == \"8\":\n                occupancy_summary(db)\n            elif choice == \"9\":\n                search_reservations(db)\n            elif choice == \"0\":\n                return\n            else:\n                error(\"Invalid option. Please choose a number from the menu.\")\n                continue\n        except DatabaseError as exc:\n            error(str(exc))\n        pause()\n",
      "lines": 395
    }
