      "number": "Q23",
      "title": "Rooms that have never been booked",
      "concept": "NOT EXISTS subquery",
      "sql": "SELECT room_number, room_type, status\nFROM room rm\nWHERE NOT EXISTS (\nSELECT 1 FROM reservation r WHERE r.room_id = rm.room_id\n)\nORDER BY room_number;",
